	distribution over $\F_q^{2m+2}$,
	\begin{gather}
		\label{eq:qld-4-13}
		\big(\hat{Q}^{\ell}
		_{[\mathrm{eval}_{(x,z,\alpha,\beta)}(\cdot)=a]}
		\big)_{\mathsf{A}\mathsf{A}'}
		\simeq_{\delta_{\mathrm{combine}}}
