		\\
		\big(\hat{Q}^{\ell}
		_{[\mathrm{eval}_{(x,z,\alpha,\beta)}(\cdot)=a]}
		\big)_{\mathsf{B}\mathsf{B}'}
		\simeq_{\delta_{\mathrm{combine}}}
		\big(\hat{Q}^{x,z,\alpha,\beta}_{a}\big)_{\mathsf{A}\mathsf{B}''}\,,
		\notag
